/*
 * verzeichnis.js - sorting and search for the directory table on quadrate.html.            [V2]
 *
 * How it fits in:
 * - quadrate.html is generated by tools/export_verzeichnis.py and already contains the complete
 *   table (one row per Quadrat, in the order A1 ... U6). Without JavaScript that table is the page [V1].
 * - This script loads no data file. It only works with the rows that are already in the page:
 *   sorting moves the existing <tr> elements, the search hides them. So the data exists once.
 * - Column headings with data-sort-type="text" or "number" get a sort button. aria-sort on the
 *   heading tells screen readers the order, and css/style.css draws the arrow from it.
 * - The search field and the status line are in the page with the attribute hidden; this script
 *   shows them, because they only work with JavaScript.
 * Classic script without modules (loaded at the end of <body>), so the page works by double-click.
 */
(function () {
    "use strict";
    // Everything lives inside this function so that our variables do not collide with other scripts.

    var CODE_COLUMN = 0;     // column with the Quadrat code (a <th scope="row">)
    var NAME_COLUMN = 2;     // column "Art / Name", e.g. "Platz: Marktplatz"

    var table = document.getElementById("directory-table");
    var tools = document.getElementById("directory-tools");
    var searchField = document.getElementById("directory-search");
    var statusLine = document.getElementById("directory-status");
    var jumpList = document.querySelector(".jump-list");

    var items = [];          // one entry per row: { row: <tr>, index: position in the original order }
    var headings = [];       // the <th> elements of the header row
    var sortColumn = CODE_COLUMN;
    var sortDirection = "ascending";   // "ascending" or "descending", the same words as aria-sort

    /* ---------------- sorting ---------------- */

    /** Returns the value a row is sorted by in one column: a number for number columns, else the text. */
    function cellValue(row, column) {
        var text = row.cells[column].textContent.trim();
        if (headings[column].getAttribute("data-sort-type") === "number") {
            return Number(text);
        }
        return text;
    }

    /**
     * Compares two rows for Array.sort(): negative = a comes first, positive = b comes first.
     * Texts are compared the German way with numbers inside the text read as numbers, so L2 comes
     * before L10 and M3 before M3a. Rows with equal values keep the Quadrat order (A1 ... U6).
     */
    function compareItems(a, b) {
        var valueA = cellValue(a.row, sortColumn);
        var valueB = cellValue(b.row, sortColumn);
        var result;
        if (typeof valueA === "number") {
            result = valueA - valueB;
        } else {
            result = valueA.localeCompare(valueB, "de", { numeric: true });
        }
        if (sortDirection === "descending") {
            result = -result;
        }
        if (result === 0) {
            result = a.index - b.index;
        }
        return result;
    }

    /** Sorts the rows and puts them back into the table body in the new order. */
    function sortRows() {
        var sorted = items.slice();       // a copy, so that items keeps the original order
        sorted.sort(compareItems);
        var body = table.tBodies[0];
        for (var i = 0; i < sorted.length; i++) {
            body.appendChild(sorted[i].row);   // appendChild moves an existing row to the end
        }
    }

    /** Scrolls the table box back to its first row, so the new result is seen from the start. */
    function scrollTableToTop() {
        table.parentElement.scrollTop = 0;     // the parent is the scrolling <div class="table-wrap">
    }

    /** Sets aria-sort on the heading of the sorted column and removes it from all other headings. */
    function updateHeadings() {
        for (var i = 0; i < headings.length; i++) {
            if (i === sortColumn) {
                headings[i].setAttribute("aria-sort", sortDirection);
            } else {
                headings[i].removeAttribute("aria-sort");
            }
        }
    }

    /**
     * Called when a sort button is pressed. A new column is sorted A-Z for text and from the
     * largest number down for numbers (most places first); pressing the same column again reverses it.
     */
    function onSortButton(column) {
        if (column === sortColumn) {
            sortDirection = sortDirection === "ascending" ? "descending" : "ascending";
        } else {
            sortColumn = column;
            if (headings[column].getAttribute("data-sort-type") === "number") {
                sortDirection = "descending";
            } else {
                sortDirection = "ascending";
            }
        }
        sortRows();
        updateHeadings();
        updateStatus();
        scrollTableToTop();
    }

    /** Puts the content of every sortable heading into a <button class="sort-button">. */
    function createSortButtons() {
        for (var i = 0; i < headings.length; i++) {
            var heading = headings[i];
            if (!heading.hasAttribute("data-sort-type")) {
                continue;                          // the column "Karte" is not sortable
            }
            var button = document.createElement("button");
            button.type = "button";
            button.className = "sort-button";
            while (heading.firstChild) {
                button.appendChild(heading.firstChild);   // moves the text (and the colour swatch)
            }
            heading.appendChild(button);
            // bind() fixes the column number i for this button; a plain function written here
            // would see the value i has after the loop.
            button.addEventListener("click", onSortButton.bind(null, i));
        }
    }

    /* ---------------- search ---------------- */

    /** Brings a text into a simple form for comparing: lower case and without spaces ("G 1" -> "g1"). */
    function normalize(text) {
        return text.toLowerCase().replace(/\s+/g, "");
    }

    /**
     * True when a row matches the search text: its code starts with it ("g" finds G1 ... G7,
     * "m3" finds M3 and M3a) or, from two letters on, the column "Art / Name" contains it
     * ("markt" finds the Marktplatz). A single letter only searches the codes, otherwise
     * "g" would also find every "Gebäude".
     */
    function rowMatches(row, query) {
        if (query === "") {
            return true;
        }
        var code = normalize(row.cells[CODE_COLUMN].textContent);
        if (code.indexOf(query) === 0) {
            return true;
        }
        if (query.length >= 2) {
            var name = normalize(row.cells[NAME_COLUMN].textContent);
            return name.indexOf(query) !== -1;
        }
        return false;
    }

    /** Hides every row that does not match the search field and updates the status line. */
    function applySearch() {
        var query = normalize(searchField.value);
        for (var i = 0; i < items.length; i++) {
            items[i].row.hidden = !rowMatches(items[i].row, query);
        }
        updateStatus();
    }

    /** Called on every change of the search field: filters the rows and shows the result from its first row. */
    function onSearchInput() {
        applySearch();
        scrollTableToTop();
    }

    /** Clears the search when a link of the jump list is used, so that the target row is visible. */
    function onJumpListClick(event) {
        if (event.target.closest("a") !== null && searchField.value !== "") {
            searchField.value = "";
            applySearch();
        }
    }

    /* ---------------- status line ---------------- */

    /**
     * Writes how many Quadrate are visible and how the table is sorted. The line has role="status",
     * so screen readers read out every change; the text is only replaced when it really changes.
     */
    function updateStatus() {
        var visible = 0;
        for (var i = 0; i < items.length; i++) {
            if (!items[i].row.hidden) {
                visible++;
            }
        }
        var text;
        if (visible === 0) {
            text = "Kein Quadrat passt zu dieser Suche. Versuche ein Kürzel wie G1 oder einen Namen wie Marktplatz.";
        } else {
            var direction = sortDirection === "ascending" ? "aufsteigend" : "absteigend";
            var columnName = headings[sortColumn].textContent.trim();
            text = visible + " von " + items.length + " Quadraten, sortiert nach " + columnName + " (" + direction + ")";
        }
        if (statusLine.textContent !== text) {
            statusLine.textContent = text;
        }
    }

    /* ---------------- start ---------------- */

    /** Collects rows and headings, adds the sort buttons and shows the search field. */
    function init() {
        if (table === null || tools === null || searchField === null || statusLine === null) {
            return;                                // not the directory page: nothing to do
        }
        var rows = table.tBodies[0].rows;
        for (var i = 0; i < rows.length; i++) {
            items.push({ row: rows[i], index: i });
        }
        headings = table.tHead.rows[0].cells;

        createSortButtons();
        updateHeadings();                          // the table starts sorted by Quadrat, A1 first
        tools.hidden = false;
        searchField.addEventListener("input", onSearchInput);
        if (jumpList !== null) {
            jumpList.addEventListener("click", onJumpListClick);
        }
        applySearch();                             // the browser may have kept a search text (back button)
    }

    init();
})();
